def max_consecutive_erasure(n, a):
    if n == 1:
        return 0

    # Check if we can erase from the start
    start_erase = 0
    for i in range(1, n):
        if a[i] - a[i-1] > 1:
            break
        start_erase += 1

    # Check if we can erase from the end
    end_erase = 0
    for i in range(n-2, -1, -1):
        if a[i+1] - a[i] > 1:
            break
        end_erase += 1

    # Check for the maximum consecutive erasure in the middle
    max_middle_erase = 0
    for i in range(1, n-1):
        if a[i+1] - a[i-1] > 2:
            max_middle_erase = max(max_middle_erase, i - (i - start_erase))

    return max(start_erase, end_erase, max_middle_erase)

